from fcp_common.rhinoAgentRpc import agent_rpc_onprem_side_pb2 as onprem
from fcp_common.rhinoAgentRpc.agent_rpc_internal_cloud_proxy_pb2 import AgentRpcResponse
from fcp_common.rhinoAgentRpc.agent_rpc_internal_cloud_proxy_pb2_grpc import RhinoCloudInternalRpcProxyServicer
from rhinoCloud.rhinoTaskServices.rhinoTaskResponseService.handle_task_response import handle_task_response

METHODS = onprem.RhinoAgentRpc.GetDescriptor().methods_by_name  # the same lookup AgentRpcClient uses


class FakeOnPremClient(RhinoCloudInternalRpcProxyServicer):
    """In-memory Rhino clients behind the real cloud->agent gRPC contract. Pinned by tests_api/contracts/ (also run on FCP Lab)."""

    def __init__(self):
        self.calls: list[tuple[str, str]] = []  # (rhino_agent_id, method_name)
        self.offline_agents: set[str] = set()
        self.scheduled: list[onprem.ScheduleTaskRequest] = []  # more handlers: SystemStatus, GetEnvironmentVariable, ...

    def AgentRpc(self, request, context):  # runs on a gRPC server thread: never touch the database here
        self.calls.append((request.rhino_agent_id, request.method_name))
        if request.rhino_agent_id in self.offline_agents:
            return AgentRpcResponse(error_message="agent not connected", error_type=AgentRpcResponse.ErrorType.TIMEOUT)
        handler = getattr(self, f"_{request.method_name}", None)
        if handler is None:  # loud on purpose: add the method here and a case to the contract suite
            return AgentRpcResponse(error_message=f"FakeOnPremClient does not implement {request.method_name}")
        request_type = getattr(onprem, METHODS[request.method_name].input_type.name)
        return AgentRpcResponse(response_data=handler(request_type.FromString(request.request_data)).SerializeToString())

    def _HealthCheck(self, request):
        return onprem.HealthCheckResponse(is_healthy=True)
    def _ScheduleTask(self, request):
        self.scheduled.append(request)
        return onprem.EmptyMessage()

    def complete_task(self, task_uid: str, status: str, output: dict) -> None:
        """Call from the test thread: runs the same handler as task_response_job (the RQ task-response worker)."""
        handle_task_response(task_uid=task_uid, task_status_str=status, task_output=output)

import datetime
from pathlib import Path

from rhinoCloud.rhinoCore.services.cloud_services.storage_service import CloudStorageServiceProviderBase, FileMetadata

FAKE_HOST = "http://object-store.fake"  # the fixture patches storage_service.requests.get to serve this host


class InMemoryStorageProvider(CloudStorageServiceProviderBase):
    """S3-shaped store in a dict. Pinned by tests_api/contracts/test_object_store_contract.py, which also runs on MinIO."""

    storage_service_prefix = "s3://"  # same as AWSStorageServiceProvider; check before relying on it

    def __init__(self):
        self.buckets: dict[str, dict[str, tuple[bytes, datetime.datetime]]] = {}

    def list_objects(self, *, bucket_name, prefix=None, filter_non_files=False) -> list[str]:
        objects = self.buckets[bucket_name]  # a missing bucket raises; the contract suite pins what MinIO does
        keys = [key for key in objects if key.startswith(prefix or "")]
        return [key for key in keys if not filter_non_files or (not key.endswith("/") and objects[key][0])]

    def upload_file_from_bytes(self, *, bucket_name: str, object_key: str, file_bytes: bytes) -> None:
        self.buckets[bucket_name][object_key] = (file_bytes, datetime.datetime.now(datetime.UTC))

    def upload_file(self, *, bucket_name: str, object_key: str, file_path: str) -> None:
        self.upload_file_from_bytes(bucket_name=bucket_name, object_key=object_key, file_bytes=Path(file_path).read_bytes())

    def generate_presigned_download_url(self, *, bucket_name, object_key, expires_in, response_disposition=None) -> str:
        return f"{FAKE_HOST}/{bucket_name}/{object_key}?expires_in={expires_in}"

    def get_file_metadata(self, *, bucket_name: str, object_key: str) -> FileMetadata:
        data, modified = self.buckets[bucket_name][object_key]
        return FileMetadata(last_modified=modified, size_bytes=len(data))

