import json
from urllib.parse import urlencode

from rest_framework.test import APIClient

from integration_test_utils.common import RhinoAPI
from integration_test_utils.rhino_api_wrapper import RhinoAPITestWrapper


class InProcessRhinoAPI(RhinoAPI):
    """The integration tests' RhinoAPI with the HTTP call swapped for DRF's APIClient: same auth (a real JWT from
    auth/obtain_token), same error handling and pagination, but no network and no shared QA."""

    def __init__(self, user_username: str, user_password: str, api_version: str = "v2"):
        super().__init__(api_version=api_version, user_username=user_username, user_password=user_password)
        self.api_base_url = "/api/"
        self.client = APIClient()

    def _request_jwt_token(self) -> str:
        credentials = {"email": self.user_username, "password": self.user_password}
        return self.client.post(f"{self.api_base_versioned_url}auth/obtain_token", credentials).json()["access"]

    def _send(self, method, url, headers=None, data=None, params=None, json_body=None, timeout=None):
        # New seam: RhinoAPI.make_call (and its page fetches) call _send() instead of requests.request().
        meta = {"HTTP_" + name.upper().replace("-", "_"): value for name, value in (headers or {}).items() if value}
        body = json.dumps(json_body) if json_body is not None else (data or "")  # multipart uploads: check per endpoint
        return self.client.generic(
            method, url, body, content_type="application/json", QUERY_STRING=urlencode(params or {}), **meta
        )


def in_process_wrapper(email: str, password: str, workgroup_uid: str) -> RhinoAPITestWrapper:  # for `api_client`
    wrapper = RhinoAPITestWrapper(user_username=email, user_password=password, workgroup_uid=workgroup_uid)
    wrapper.api = InProcessRhinoAPI(email, password)
    return wrapper

// `npm run verify` checks what changed since main; `npm run verify -- --all` checks everything (CI).
import {execFileSync, spawnSync} from "node:child_process"

const all = process.argv.includes("--all")
const git = (...args: string[]) => execFileSync("git", args, {encoding: "utf8"}).trim()
const base = process.env.VERIFY_BASE ?? git("merge-base", "HEAD", "origin/main")
const changed = [
	...git("diff", "--name-only", "--relative", "--diff-filter=ACMR", base).split("\n"),
	...git("ls-files", "--others", "--exclude-standard").split("\n")
].filter((file) => /\.(ts|tsx|css|json)$/.test(file))
const code = changed.filter((file) => /^(src|test)\/.*\.tsx?$/.test(file))

const steps: [string, string[]][] = [["types", ["tsc", "--noEmit", "--pretty", "false"]]]
if (all || changed.length > 0) steps.unshift(["lint", ["biome", "check", ...(all ? ["."] : changed)]])
if (all) steps.push(["unit tests", ["vitest", "run", ...(process.env.VITEST_MONOCART ? ["--coverage"] : [])]])
else if (code.length > 0)
	steps.push(["related unit tests", ["vitest", "related", ...code, "--run", "--passWithNoTests"]])
// Affected stories: decide with the FE guild (@storybook/addon-vitest would make them part of `vitest related`).

const results = steps.map(([name, args]) => ({name, ok: spawnSync("npx", args, {stdio: "inherit"}).status === 0}))
console.log(`\nverify: ${all ? "all files" : `${changed.length} changed files since ${base.slice(0, 7)}`}`)
for (const {name, ok} of results) console.log(`${ok ? "pass" : "FAIL"}  ${name}`)
process.exit(results.every(({ok}) => ok) ? 0 : 1)

